/**
 * Developer Mode assessments: 5 retryable practice MCQs + 1 Master Challenge
 * for each of the 24 curriculum lessons.
 *
 * Practice questions reinforce understanding; wrong answers show explanations
 * and allow unlimited retries with no penalty.
 *
 * Master Challenges test the chapter's core concept. The correct answer index
 * is evaluated server-side — the frontend never validates it before submission.
 */
import type { MasterChallenge, Question } from './types';

const q = (
  prompt: string,
  options: [string, string, string, string],
  answer: 0 | 1 | 2 | 3,
  explanation: string,
): Question => ({ prompt, options, answer, explanation });

const mc = (
  prompt: string,
  options: [string, string, string, string],
  answer: 0 | 1 | 2 | 3,
  explanation: string,
  tokenLabel: string,
  dropZoneHint: string,
): MasterChallenge => ({ prompt, options, answer, explanation, tokenLabel, dropZoneHint });

